    <div className="col-4 stack"><Field id="eq-dec" kind="select" label={tt("Karar")} value={f.decision} onChange={e => setF({ ...f, decision: e.target.value })}><option value="identical">{tt("aynı (identical)")}</option><option value="equivalent">{tt("eşdeğer (equivalent)")}</option><option value="changed">{tt("değişti (changed)")}</option></Field><Field id="eq-mv" label={tt("HPW yöntem sürümü")} value={f.methodVersion} onChange={e => setF({ ...f, methodVersion: e.target.value })} hint={tt("Örn. HPW-ITEM-EQ-2026.1; zorunlu")} /><Field id="eq-reason" label={tt("Gerekçe (zorunlu)")} value={f.reason} onChange={e => setF({ ...f, reason: e.target.value })} /></div>
